const input = $input.first().json;
const system = `You are an AI code-review critic and validator. Validate whether each proposed finding is supported by the supplied PR diff and, where applicable, by the supplied internal standard evidence.\n\nReturn only valid JSON: {"validations":[{"finding_id":"AI-001","validation":"VALID|QUESTIONABLE|INVALID","confidence":0.0,"reason":""}]}.\n\nReject findings as INVALID when the diff does not support them, when an internal-standard finding lacks matching standard evidence, or when the finding is speculative. Use QUESTIONABLE when evidence exists but is incomplete or should be presented cautiously.`;
const request = {
  model: $env.OPENAI_VALIDATOR_MODEL || $env.OPENAI_CODE_REVIEW_MODEL,
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: JSON.stringify({ pr_context: input.pr_context, standards: input.standards, review: { summary: input.summary, findings: input.findings } }, null, 2) }
  ]
};
return [{ json: { request, original: input } }];

const original = $('Build Validation Request').first().json.original;
const minConfidence = Number($env.AI_REVIEW_MIN_CONFIDENCE || 0.80);
const response = $input.first().json;
let validations = [];
if (!response.error) {
  try {
    const content = response.choices?.[0]?.message?.content || '{"validations":[]}';
    const parsed = typeof content === 'string' ? JSON.parse(content) : content;
    validations = Array.isArray(parsed.validations) ? parsed.validations : [];
  } catch (error) {
    validations = [];
  }
}
const validationById = new Map(validations.map((v) => [v.finding_id, { validation: ['VALID','QUESTIONABLE','INVALID'].includes(v.validation) ? v.validation : 'QUESTIONABLE', confidence: Math.max(0, Math.min(1, Number(v.confidence || 0))), reason: v.reason || '' }]));
const valid_findings = [];
const rejected_findings = [];
for (const finding of original.findings || []) {
  const validation = validationById.get(finding.id) || { validation: response.error ? 'QUESTIONABLE' : 'INVALID', confidence: 0, reason: response.error ? 'Validator unavailable; finding not rejected automatically but marked questionable.' : 'Validator returned no support for this finding.' };
  const enriched = { ...finding, validation: validation.validation, validation_confidence: validation.confidence, validation_reason: validation.reason };
  if (validation.validation === 'INVALID' || finding.confidence < minConfidence) rejected_findings.push(enriched);
  else valid_findings.push(enriched);
}
const counts = { critical: 0, high: 0, medium: 0, low: 0, info: 0 };
for (const f of valid_findings) counts[f.severity.toLowerCase()]++;
return [{ json: { pr_metadata: original.pr_metadata, pr_context: original.pr_context, standards: original.standards, summary: { files_reviewed: original.summary?.files_reviewed || original.pr_context?.files_changed || 0, ...counts }, valid_findings, rejected_findings, validator_available: !response.error, min_confidence: minConfidence } }];
